/**
 * my-ai-infra SDD workbench (read-only): two model-facing tools over the
 * session workspace's `mai-specs/` directory — `mai_features` for Feature
 * navigation and acceptance summaries, `mai_spec_read` for reading one spec
 * artifact by its semantic address. Load through the overlay generated by
 * `setup.mjs` (`dsh <profile> --patch plugins/mai-spec-workbench/cordis.yml`).
 * @module mai-spec-workbench
 */

import type { Context } from '@deepseek-ai/cordis'
import type {} from '@deepseek-ai/dsh-fs'
import type {} from '@deepseek-ai/dsh-working-directory'
import { applyFeaturesTool } from './tool-features.ts'
import { applySpecReadTool } from './tool-spec-read.ts'

export const name = 'mai-spec-workbench'

export const inject = ['tools', 'fs', 'workingDirectory']

/**
 * Register both tools. Each registration is an effect of this plugin scope and
 * unregisters when the plugin unloads.
 * @param ctx - plugin context; required services are ready before this runs.
 */
export function apply(ctx: Context): void {
  applyFeaturesTool(ctx)
  applySpecReadTool(ctx)
}
